from .money import MAX_CENTS, cents_to_amount, format_amount, parse_cents

def make_invoice(amounts):
    items = list(amounts)  # copy; the caller's input is never modified
    total = 0
    for item in items:
        total += parse_cents(item)
    if total > MAX_CENTS:
        raise ValueError("total exceeds 1000000.00")
    return {"total": format_amount(cents_to_amount(total)), "count": len(items)}
